int init_pdl_types_proto_struct(void)
{
    protocol_t *protocol_struct;
    size_t i;

    /* mmt-dpi ignores a protocol name that is already registered (names
     * compare case-insensitively): refuse to load instead. */
    if (get_protocol_id_by_name(PROTO_PDL_TYPES_ALIAS) != 0) {
        mmt_log_error("init_pdl_types_proto_struct: protocol name %s is already registered", PROTO_PDL_TYPES_ALIAS);
        return 0;
    }
    protocol_struct = init_protocol_struct_for_registration(PROTO_PDL_TYPES, PROTO_PDL_TYPES_ALIAS);
    if (protocol_struct == NULL) {
        mmt_log_error("init_pdl_types_proto_struct: protocol id %d is out of range or already registered", PROTO_PDL_TYPES);
        return 0;
    }
    for (i = 0; i < sizeof(pdl_types_attributes_metadata) / sizeof(pdl_types_attributes_metadata[0]); i++) {
        if (!register_attribute_with_protocol(protocol_struct, &pdl_types_attributes_metadata[i])) {
            mmt_log_error("init_pdl_types_proto_struct: cannot register attribute %s", pdl_types_attributes_metadata[i].alias);
            return 0;
        }
    }
    if (!register_protocol(protocol_struct, PROTO_PDL_TYPES)) {
        mmt_log_error("init_pdl_types_proto_struct: cannot register protocol %d", PROTO_PDL_TYPES);
        return 0;
    }
    return 1;
}

#ifndef CORE
int init_proto(void)
{
    return init_pdl_types_proto_struct();
}
#endif
